import {
  createContext,
  useContext,
  useEffect,
  useState,
  useCallback,
  useMemo,
  ReactNode,
} from 'react';
import { supabase } from '../lib/supabase';
import { queryClient } from '../lib/query-client';
import { type User } from '@supabase/supabase-js';

export interface AuthProfile {
  role: 'admin' | 'staff' | string;
  full_name: string | null;
  last_seen_at?: string | null;
}

interface AuthContextType {
  user: User | null;
  role: string | null;
  profile: AuthProfile | null;
  isAdmin: boolean;
  loading: boolean;
  signOut: () => Promise<void>;
  updateProfileName: (newName: string) => Promise<{ success: boolean; error?: string }>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider = ({ children }: { children: ReactNode }) => {
  const [user, setUser] = useState<User | null>(null);
  const [role, setRole] = useState<string | null>(null); // 'admin' | 'staff'
  const [loading, setLoading] = useState(true);
  const [profile, setProfile] = useState<AuthProfile | null>(null);

  // Cleanup legacy view_as_user storage
  useEffect(() => {
    localStorage.removeItem('view_as_user');
  }, []);

  useEffect(() => {
    let mounted = true;

    const initAuth = async () => {
      try {
        const {
          data: { session },
          error,
        } = await supabase.auth.getSession();
        if (error) throw error;

        if (session?.user) {
          if (mounted) setUser(session.user);

          const cachedRole = localStorage.getItem(`role_${session.user.id}`);
          if (cachedRole && mounted) {
            setRole(cachedRole);
            setLoading(false);
            fetchProfileWithTimeout(session.user.id, true);
          } else {
            await fetchProfileWithTimeout(session.user.id, false);
          }
        } else {
          if (mounted) setLoading(false);
        }
      } catch (err) {
        console.error('Auth initialization error:', err);
        if (mounted) setLoading(false);
      }
    };

    initAuth();

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange(async (event, session) => {
      if (session?.user) {
        if (mounted) setUser(session.user);

        if (event === 'SIGNED_IN' || event === 'INITIAL_SESSION') {
          const cachedRole = localStorage.getItem(`role_${session.user.id}`);
          if (cachedRole && mounted) {
            setRole(cachedRole);
            setLoading(false);

            fetchProfileWithTimeout(session.user.id, true);

            // Kickstart: Clean and Resume to prevent 'Zombie Orders'
            import('../lib/query-client').then(({ cleanupCorruptedMutations }) => {
              cleanupCorruptedMutations().then(() => {
                queryClient.resumePausedMutations().then(() => {
                  // Mutations resumed post-login
                  // If no mutations are running, force absolute truth from server now
                  if (queryClient.isMutating() === 0) {
                    queryClient.invalidateQueries();
                  }
                });
              });
            });
          } else {
            await fetchProfileWithTimeout(session.user.id, false);

            import('../lib/query-client').then(({ cleanupCorruptedMutations }) => {
              cleanupCorruptedMutations().then(() => {
                queryClient.resumePausedMutations().then(() => {
                  if (queryClient.isMutating() === 0) {
                    queryClient.invalidateQueries();
                  }
                });
              });
            });
          }
        }
      } else if (event === 'SIGNED_OUT') {
        if (mounted) {
          // On generalized SIGNED_OUT event (could be session expiry or other tab logout)
          // we play it safe and only remove sensitive queries, preserving the mutation queue.
          queryClient.removeQueries();

          setUser(null);
          setRole(null);
          setProfile(null);
          setLoading(false);

          if (window.location.pathname !== '/login') {
            window.location.href = '/login';
          }
        }
      }
    });

    // Listen for global 401 auth errors from QueryClient
    const handleAuthError = () => {
      console.warn(
        '[AuthContext] 401 detected. Session expired. Preserving mutations, clearing queries.'
      );
      // 401 is involuntary logout: remove queries only
      queryClient.removeQueries();

      // Clear app state and redirect
      setUser(null);
      setRole(null);
      setProfile(null);

      if (window.location.pathname !== '/login') {
        window.location.href = '/login';
      }
    };

    window.addEventListener('auth-error-401', handleAuthError);

    return () => {
      mounted = false;
      subscription?.unsubscribe();
      window.removeEventListener('auth-error-401', handleAuthError);
    };
  }, []);

  // Update last seen
  useEffect(() => {
    if (user) {
      const updateLastSeen = async () => {
        await supabase
          .from('profiles')
          .update({ last_seen_at: new Date().toISOString() })
          .eq('id', user.id);
      };
      updateLastSeen();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- intentionally depends on user.id only to avoid re-running on every user object change
  }, [user?.id]);

  const fetchProfileWithTimeout = async (userId: string, isBackground = false) => {
    const timeoutMs = 3000;
    const timeout = new Promise((resolve) => setTimeout(() => resolve('timeout'), timeoutMs));

    const fetchProfile = async () => {
      const { data, error } = await supabase
        .from('profiles')
        .select('role, full_name, last_seen_at')
        .eq('id', userId)
        .single();
      return { data, error };
    };

    try {
      const result = await Promise.race([fetchProfile(), timeout]);

      if (result === 'timeout') {
        if (!isBackground) setRole('staff');
      } else if (
        typeof result === 'object' &&
        result !== null &&
        'error' in result &&
        result.error
      ) {
        if (!isBackground) setRole('staff');
      } else if (typeof result === 'object' && result !== null && 'data' in result && result.data) {
        const profileData = result.data as AuthProfile;
        setRole(profileData.role);
        setProfile(profileData);
        localStorage.setItem(`role_${userId}`, profileData.role);
      } else {
        if (!isBackground) setRole('staff');
      }
    } catch (e) {
      console.error('Profile fetch exception:', e);
      if (!isBackground) setRole('staff');
    } finally {
      if (!isBackground) setLoading(false);
    }
  };

  const updateProfileName = useCallback(
    async (newName: string) => {
      if (!user) return { success: false, error: 'No user session' };

      try {
        const { error } = await supabase
          .from('profiles')
          .update({ full_name: newName })
          .eq('id', user.id);

        if (error) throw error;

        setProfile((prev) => (prev ? { ...prev, full_name: newName } : null));
        return { success: true };
      } catch (err) {
        console.error('Update profile error:', err);
        return { success: false, error: err instanceof Error ? err.message : String(err) };
      }
    },
    [user]
  );

  const signOut = useCallback(async () => {
    setLoading(true);

    // Voluntary Logout: Clear EVERYTHING (Queries + Mutations)
    // This prevents data leakage between different users on the same device.
    queryClient.clear();

    await supabase.auth.signOut();

    // Clear picking-related localStorage on Logout
    localStorage.removeItem('picking_cart_items');
    localStorage.removeItem('picking_order_number');
    localStorage.removeItem('active_picking_list_id');
    localStorage.removeItem('picking_session_mode');
    Object.keys(localStorage).forEach((key) => {
      if (key.startsWith('double_check_progress_')) {
        localStorage.removeItem(key);
      }
    });

    setRole(null);
    setProfile(null);
    setUser(null);
    setLoading(false);
  }, []);

  const value = useMemo(
    () => ({
      user,
      role,
      profile,
      isAdmin: role === 'admin',
      loading,
      signOut,
      updateProfileName,
    }),
    [user, role, profile, loading, signOut, updateProfileName]
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

import { createContext, useContext, useState, useCallback, ReactNode } from 'react';

interface ConfirmationState {
  isOpen: boolean;
  title: string;
  message: string;
  onConfirm: () => void;
  onClose: () => void;
  confirmText?: string;
  cancelText?: string;
  variant?: 'danger' | 'warning' | 'info';
}

interface ConfirmationContextType {
  confirmationState: ConfirmationState;
  showConfirmation: (
    title: string,
    message: string,
    onConfirm: () => void,
    onClose?: () => void,
    confirmText?: string,
    cancelText?: string,
    variant?: 'danger' | 'warning' | 'info'
  ) => void;
  hideConfirmation: () => void;
}

const ConfirmationContext = createContext<ConfirmationContextType | undefined>(undefined);

export const ConfirmationProvider = ({ children }: { children: ReactNode }) => {
  const [confirmationState, setConfirmationState] = useState<ConfirmationState>({
    isOpen: false,
    title: '',
    message: '',
    onConfirm: () => {},
    onClose: () => {},
    confirmText: 'Confirm',
    cancelText: 'Cancel',
    variant: 'danger',
  });

  const showConfirmation = useCallback(
    (
      title: string,
      message: string,
      onConfirm: () => void,
      onClose?: () => void,
      confirmText?: string,
      cancelText?: string,
      variant?: 'danger' | 'warning' | 'info'
    ) => {
      setConfirmationState({
        isOpen: true,
        title,
        message,
        onConfirm: () => {
          onConfirm();
          setConfirmationState((prev) => ({ ...prev, isOpen: false }));
        },
        onClose: () => {
          onClose?.();
          setConfirmationState((prev) => ({ ...prev, isOpen: false }));
        },
        confirmText,
        cancelText,
        variant: variant || 'danger',
      });
    },
    []
  );

  const hideConfirmation = useCallback(() => {
    setConfirmationState((prev) => ({ ...prev, isOpen: false }));
  }, []);

  return (
    <ConfirmationContext.Provider value={{ confirmationState, showConfirmation, hideConfirmation }}>
      {children}
    </ConfirmationContext.Provider>
  );
};

export const useConfirmation = () => {
  const context = useContext(ConfirmationContext);
  if (!context) {
    throw new Error('useConfirmation must be used within a ConfirmationProvider');
  }
  return context;
};

import { createContext, useContext, ReactNode } from 'react';
import { useErrorHandler } from '../hooks/useErrorHandler';

interface ErrorContextType {
  error: {
    isOpen: boolean;
    title: string;
    message: string;
    details?: string;
  };
  showError: (message: string, details?: string, title?: string) => void;
  clearError: () => void;
}

const ErrorContext = createContext<ErrorContextType | undefined>(undefined);

export const ErrorProvider = ({ children }: { children: ReactNode }) => {
  const { error, showError, clearError } = useErrorHandler();

  return (
    <ErrorContext.Provider value={{ error, showError, clearError }}>
      {children}
    </ErrorContext.Provider>
  );
};

export const useError = () => {
  const context = useContext(ErrorContext);
  if (!context) {
    throw new Error('useError must be used within an ErrorProvider');
  }
  return context;
};

/**
 * Modal Manager — Context + Root Render pattern
 *
 * See `docs/modal-pattern.md` for the full architectural decision.
 *
 * Golden rule: no critical modal lives inside the component that opens it.
 *
 * Usage:
 *   const { open, close } = useModal();
 *   open({ type: 'item-detail', item });
 */

import { createContext, useCallback, useContext, useMemo, useState, type ReactNode } from 'react';
import { InventorySnapshotModal } from '../features/inventory/components/InventorySnapshotModal';
import { ItemDetailView } from '../features/inventory/components/ItemDetailView';
import { PickingSummaryModalById } from '../components/orders/PickingSummaryModalById';
import { NotificationHistoryModal } from '../components/ui/NotificationHistoryModal';
import type { InventoryItemWithMetadata, InventoryItemInput } from '../schemas/inventory.schema';

type ItemDetailSavePayload = InventoryItemInput & {
  length_in?: number;
  width_in?: number;
  height_in?: number;
};

export type ModalState =
  | { type: 'inventory-snapshot' }
  | {
      type: 'item-detail';
      item: InventoryItemWithMetadata | null;
      mode?: 'add' | 'edit';
      screenType?: string;
      onSave?: (data: ItemDetailSavePayload) => Promise<void> | void;
      onDelete?: () => Promise<void> | void;
    }
  | { type: 'picking-summary'; listId: string }
  | { type: 'notification-history' }
  | null;

interface ModalContextValue {
  open: (modal: NonNullable<ModalState>) => void;
  close: () => void;
}

const ModalContext = createContext<ModalContextValue | null>(null);

export const ModalProvider = ({ children }: { children: ReactNode }) => {
  const [modal, setModal] = useState<ModalState>(null);

  const open = useCallback((m: NonNullable<ModalState>) => setModal(m), []);
  const close = useCallback(() => setModal(null), []);

  const value = useMemo(() => ({ open, close }), [open, close]);

  return (
    <ModalContext.Provider value={value}>
      {children}

      {/* All critical modals live here — survive opener unmounting */}
      {modal?.type === 'inventory-snapshot' && <InventorySnapshotModal isOpen onClose={close} />}

      {modal?.type === 'picking-summary' && (
        <PickingSummaryModalById listId={modal.listId} onClose={close} />
      )}

      {modal?.type === 'notification-history' && <NotificationHistoryModal onClose={close} />}

      {modal?.type === 'item-detail' && (
        <ItemDetailView
          isOpen
          onClose={close}
          initialData={modal.item}
          mode={modal.mode ?? 'edit'}
          screenType={modal.screenType ?? modal.item?.warehouse}
          onSave={async (data) => {
            await modal.onSave?.(data);
            close();
          }}
          onDelete={
            modal.onDelete
              ? async () => {
                  await modal.onDelete?.();
                  close();
                }
              : undefined
          }
        />
      )}
    </ModalContext.Provider>
  );
};

export const useModal = () => {
  const ctx = useContext(ModalContext);
  if (!ctx) throw new Error('useModal must be used within a ModalProvider');
  return ctx;
};

import React, {
  createContext,
  useContext,
  useState,
  useRef,
  ReactNode,
  useCallback,
  useMemo,
} from 'react';
import { useAuth } from './AuthContext';
import { useInventory } from '../features/inventory/hooks/useInventoryData';
import { useError } from './ErrorContext';
import { usePickingCart, CartItem } from '../features/picking/hooks/usePickingCart';
import { usePickingSync } from '../features/picking/hooks/usePickingSync';
import { usePickingActions } from '../features/picking/hooks/usePickingActions';
import { usePickingNotes, PickingNote } from '../features/picking/hooks/usePickingNotes';
import type { Customer } from '../types/schema';
import type { InventoryItem } from '../schemas/inventory.schema';
import { useLocationManagement } from '../features/inventory/hooks/useLocationManagement';
import {
  getOptimizedPickingPath,
  calculatePalletsWithBikeAwareness,
  type Pallet,
} from '../utils/pickingLogic';
import { useBikeSkuSet } from '../hooks/useBikeSkuSet';

interface PickingContextType {
  cartItems: CartItem[];
  setCartItems: React.Dispatch<React.SetStateAction<CartItem[]>>;
  activeListId: string | null;
  setActiveListId: (id: string | null) => void;
  orderNumber: string | null;
  setOrderNumber: (num: string | null) => void;
  customer: Customer | null;
  setCustomer: (cust: Customer | null) => void;
  loadNumber: string | null;
  setLoadNumber: (num: string | null) => void;
  listStatus: string;
  shippingType: string | null;
  isWaitingInventory: boolean;
  setIsWaitingInventory: (val: boolean) => void;
  checkedBy: string | null;
  ownerId: string | null;
  correctionNotes: string | null;
  notes: PickingNote[];
  isNotesLoading: boolean;
  addNote: (message: string) => Promise<void>;
  sessionMode: 'idle' | 'picking' | 'double_checking' | 'reopened';
  setSessionMode: (mode: 'idle' | 'picking' | 'double_checking' | 'reopened') => void;
  pallets: Pallet[];

  onStartSession: () => void;

  addToCart: (item: InventoryItem) => void;
  updateCartQty: (item: InventoryItem, change: number) => void;
  setCartQty: (item: InventoryItem, qty: number) => void;
  removeFromCart: (item: Partial<InventoryItem>) => void;
  clearCart: () => void;
  getAvailableStock: (item: Partial<InventoryItem>) => {
    available: number;
    reservedByOthers: number;
    totalStock: number;
    inMyCart: number;
  };

  completeList: (
    metrics?: { pallets_qty: number; total_units: number },
    id?: string
  ) => Promise<void>;
  markAsReady: (items?: CartItem[], orderNum?: string) => Promise<string | null>;
  lockForCheck: (id: string) => Promise<void>;
  releaseCheck: (id: string) => Promise<void>;
  parkOrder: (id: string) => Promise<void>;
  returnToPicker: (id: string, notes: string) => Promise<void>;
  revertToPicking: () => Promise<void>;
  deleteList: (id: string | null, keepLocalState?: boolean) => Promise<void>;
  takeOverOrder: (id: string) => Promise<void>;
  claimAsPicker: (listId?: string) => Promise<void>;

  loadExternalList: (id: string) => Promise<unknown>;
  loadReopenedOrder: (id: string, reason?: string) => Promise<void>;
  resumeReopenedOrder: (id: string) => Promise<void>;

  generatePickingPath: () => Promise<void>;

  reopenOrder: (listId: string, reason?: string) => Promise<void>;
  restoreCancelledOrder: (listId: string, reason?: string) => Promise<void>;
  recompleteOrder: (listId: string, palletsQty: number, totalUnits: number) => Promise<void>;
  cancelReopen: (listId: string) => Promise<void>;
  completeAddonGroup: (
    sourceId: string,
    targetId: string,
