const PickingContext = createContext<PickingContextType | undefined>(undefined);

export const PickingProvider = ({ children }: { children: ReactNode }) => {
  // 1. External dependencies
  const { user } = useAuth();
  const { reservedQuantities } = useInventory();
  const { showError } = useError();
  const { locations } = useLocationManagement();

  // 2. Shared/Lifted State
  const [activeListId, setActiveListId] = useState<string | null>(null);
  const [listStatus, setListStatus] = useState<string>('active');
  const [isWaitingInventory, setIsWaitingInventory] = useState(false);
  const [shippingType, setShippingType] = useState<string | null>(null);
  const [checkedBy, setCheckedBy] = useState<string | null>(null);
  const [ownerId, setOwnerId] = useState<string | null>(null);
  const [correctionNotes, setCorrectionNotes] = useState<string | null>(null);
  const [sessionMode, setSessionMode] = useState<
    'idle' | 'picking' | 'double_checking' | 'reopened'
  >('idle');

  // Workflow Lock: prevents loadSession from overwriting activeListId during a workflow
  const isInWorkflowRef = useRef(false);

  // Initialization State
  const [isInitializing, setIsInitializing] = useState(false);
  const [pendingItem, setPendingItem] = useState<InventoryItem | null>(null);

  const [isSaving, setIsSaving] = useState(false);
  const [lastSaved, setLastSaved] = useState<Date | null>(null);
  const [isLoaded, setIsLoaded] = useState(false);

  // 3. Hook Integration
  const {
    cartItems,
    setCartItems,
    orderNumber,
    setOrderNumber,
    customer,
    setCustomer,
    loadNumber,
    setLoadNumber,
    addToCart: addToCartInternal,
    updateCartQty,
    setCartQty,
    removeFromCart,
    clearCart,
    loadFromLocalStorage,
    getAvailableStock,
  } = usePickingCart({
    sessionMode,
    reservedQuantities,
  });

  // 4. Automated Pallet Calculation
  // This calculates pallets once the session moves into picking/double_checking mode
  // fulfilling the requirement of grouping "when receiving from DB"
  const bikeSkuSet = useBikeSkuSet(cartItems.map((i) => i.sku));
  const pallets = useMemo(() => {
    if (sessionMode === 'idle' || cartItems.length === 0) return [];
    const optimizedItems = getOptimizedPickingPath(cartItems, locations);
    return calculatePalletsWithBikeAwareness(optimizedItems, bikeSkuSet);
  }, [cartItems, locations, sessionMode, bikeSkuSet]);

  const resetSession = useCallback(
    (skipState = false) => {
      // Atomic Reset
      if (!skipState) {
        clearCart();
        setActiveListId(null);
        setListStatus('active');
        setIsWaitingInventory(false);
        setShippingType(null);
        setCheckedBy(null);
        setOwnerId(null);
        setCorrectionNotes(null);
        setSessionMode('idle');
        setOrderNumber(null);
        setCustomer(null);
        setLoadNumber(null);
        setIsInitializing(false);
      }

      // Comprehensive localStorage cleanup
      const keysToRemove = [
        'picking_cart_items',
        'picking_order_number',
        'picking_customer_obj',
        'picking_load_number',
        'active_picking_list_id',
        'picking_session_mode',
      ];

      keysToRemove.forEach((k) => localStorage.removeItem(k));

      // Also clean up double check progress if any
      Object.keys(localStorage).forEach((key) => {
        if (key.startsWith('double_check_progress_')) {
          localStorage.removeItem(key);
        }
      });

      console.log('🧹 [Atomic Reset] Session cleared');
    },
    [
      clearCart,
      setOrderNumber,
      setCustomer,
      setLoadNumber,
      setActiveListId,
      setListStatus,
      setCheckedBy,
      setOwnerId,
      setCorrectionNotes,
      setSessionMode,
      setIsInitializing,
    ]
  );

  const { loadExternalList } = usePickingSync({
    user,
    sessionMode,
    cartItems,
    orderNumber,
    activeListId,
    customer,
    setCustomer,
    loadNumber,
    setLoadNumber,
    listStatus,
    correctionNotes,
    checkedBy,
    setCartItems,
    setActiveListId,
    setOrderNumber,
    setListStatus,
    setIsWaitingInventory,
    setShippingType,
    setCheckedBy,
    ownerId,
    setOwnerId,
    setCorrectionNotes,
    setSessionMode,
    loadFromLocalStorage,
    showError,
    resetSession,
    setIsSaving,
    setIsLoaded,
    setLastSaved,
    isSaving,
    isLoaded,
    lastSaved,
    isInWorkflowRef,
  });

  const {
    completeList,
    markAsReady,
    lockForCheck,
    releaseCheck,
    parkOrder,
    returnToPicker,
    revertToPicking,
    deleteList,
    generatePickingPath,
    updateCustomerDetails,
    takeOverOrder,
    claimAsPicker,
    reopenOrder,
    restoreCancelledOrder,
    recompleteOrder,
    cancelReopen,
    completeAddonGroup,
  } = usePickingActions({
    user,
    activeListId,
    cartItems,
    orderNumber,
    customer,
    sessionMode,
    setCartItems,
    setActiveListId,
    setOrderNumber,
    setCustomer,
    setListStatus,
    setCheckedBy,
    setOwnerId,
    setCorrectionNotes,
    setSessionMode,
    setIsSaving,
    resetSession,
    ownerId,
    loadNumber,
    setLoadNumber,
    isInWorkflowRef,
  });

  const { notes, isLoading: isNotesLoading, addNote: addNoteRaw } = usePickingNotes(activeListId);

  const addNote = useCallback(
    async (message: string) => {
      if (!user) return;
      await addNoteRaw(user.id, message);
    },
    [user, addNoteRaw]
  );

  const loadReopenedOrder = useCallback(
    async (listId: string, reason?: string) => {
      isInWorkflowRef.current = true;
      try {
        await reopenOrder(listId, reason);
        await loadExternalList(listId);
        // Override the 'double_checking' that loadExternalList hardcodes
        setSessionMode('reopened');
      } catch (err) {
        console.error('Failed to load reopened order:', err);
      } finally {
        isInWorkflowRef.current = false;
      }
    },
    [reopenOrder, loadExternalList, setSessionMode, isInWorkflowRef]
  );

  const resumeReopenedOrder = useCallback(
    async (listId: string) => {
      isInWorkflowRef.current = true;
      try {
        await loadExternalList(listId);
        setSessionMode('reopened');
      } catch (err) {
        console.error('Failed to resume reopened order:', err);
      } finally {
        isInWorkflowRef.current = false;
      }
    },
    [loadExternalList, setSessionMode, isInWorkflowRef]
  );

  const addToCart = useCallback(
    (item: InventoryItem) => {
      // If idle and no order number, store item and show modal
      if (sessionMode === 'idle' && !orderNumber) {
        setPendingItem(item);
        setIsInitializing(true);
        return;
      }

      // Transition to picking mode if idle (with order number)
      if (sessionMode === 'idle') {
        setSessionMode('picking');
        localStorage.setItem('picking_session_mode', 'picking');
      }

      addToCartInternal(item);
    },
    [sessionMode, orderNumber, setSessionMode, addToCartInternal]
  );

  const startNewSession = useCallback(
    async (
      strategy: 'auto' | 'manual' | 'resume',
      manualOrderNumber?: string,
      customerData?: Customer | string
    ) => {
      // Capture pending item before reset
      const itemToAdd = pendingItem;

      // Clear initialization state
      setIsInitializing(false);
      setPendingItem(null);

      // Clean slate for new session
      resetSession(true);

      let newOrderNumber = manualOrderNumber;

      if (strategy === 'auto') {
        const dateStr = new Date().toISOString().slice(2, 10).replace(/-/g, '');
        const random = Math.floor(Math.random() * 1000)
          .toString()
          .padStart(3, '0');
        newOrderNumber = `ORD-${dateStr}-${random}`;
      }

      if (newOrderNumber) {
        setOrderNumber(newOrderNumber);
        localStorage.setItem('picking_order_number', newOrderNumber);
      }

      if (customerData) {
        if (typeof customerData === 'string') {
          // Temporary customer object for quick sessions
          const quickCustomer = { name: customerData } as Customer;
          setCustomer(quickCustomer);
          localStorage.setItem('picking_customer_obj', JSON.stringify(quickCustomer));
        } else {
          setCustomer(customerData);
          localStorage.setItem('picking_customer_obj', JSON.stringify(customerData));
        }
      }

      // Start in Picking Mode (direct to active, no building step)
      setSessionMode('picking');
      localStorage.setItem('picking_session_mode', 'picking');

      // Now add the pending item to cart
      if (itemToAdd) {
        addToCartInternal(itemToAdd);
      }
    },
    [pendingItem, addToCartInternal, resetSession, setOrderNumber, setCustomer, setSessionMode]
  );

  const startManualSession = useCallback(() => {
    setIsInitializing(true);
  }, []);

  const cancelInitialization = useCallback(() => {
    setIsInitializing(false);
    setPendingItem(null);
  }, []);

  const onStartSession = useCallback(() => {
    if (sessionMode === 'idle') startManualSession();
  }, [sessionMode, startManualSession]);

  const value: PickingContextType = useMemo(
    () => ({
      cartItems,
      setCartItems,
      activeListId,
      setActiveListId,
      orderNumber,
      setOrderNumber,
      customer,
      setCustomer,
      loadNumber,
      setLoadNumber,
      listStatus,
      shippingType,
      isWaitingInventory,
      setIsWaitingInventory,
      checkedBy,
      ownerId,
      correctionNotes,
      notes,
      isNotesLoading,
      addNote,
      sessionMode,
      setSessionMode,
      pallets,
      addToCart,
      updateCartQty,
      setCartQty,
      removeFromCart,
      clearCart,
      getAvailableStock,
      completeList,
      markAsReady,
      lockForCheck,
      releaseCheck,
      parkOrder,
      returnToPicker,
      revertToPicking,
      deleteList,
      loadExternalList,
      loadReopenedOrder,
      resumeReopenedOrder,
      generatePickingPath,
      reopenOrder,
      restoreCancelledOrder,
      recompleteOrder,
      cancelReopen,
      completeAddonGroup,
      takeOverOrder,
      claimAsPicker,
      isLoaded,
      isSaving,
      lastSaved,
      resetSession,
      onStartSession,
      updateCustomerDetails,
      // removed duplicate updateCustomerDetails
      startNewSession,
      isInitializing,
      setIsInitializing,
      pendingItem,
      startManualSession,
      cancelInitialization,
    }),
    [
      cartItems,
      setCartItems,
      activeListId,
      setActiveListId,
      orderNumber,
      setOrderNumber,
      customer,
      setCustomer,
      loadNumber,
      setLoadNumber,
      listStatus,
      shippingType,
      isWaitingInventory,
      setIsWaitingInventory,
      checkedBy,
      ownerId,
      correctionNotes,
      notes,
      isNotesLoading,
      addNote,
      sessionMode,
      setSessionMode,
      pallets,
      addToCart,
      updateCartQty,
      setCartQty,
      removeFromCart,
      clearCart,
      getAvailableStock,
      completeList,
      markAsReady,
      lockForCheck,
      releaseCheck,
      parkOrder,
      returnToPicker,
      revertToPicking,
      takeOverOrder,
      claimAsPicker,
      deleteList,
      loadExternalList,
      loadReopenedOrder,
      resumeReopenedOrder,
      generatePickingPath,
      reopenOrder,
      restoreCancelledOrder,
      recompleteOrder,
      cancelReopen,
      completeAddonGroup,
      isLoaded,
      isSaving,
      lastSaved,
      resetSession,
      updateCustomerDetails,
      startNewSession,
      isInitializing,
      setIsInitializing,
      pendingItem,
      onStartSession,
      startManualSession,
      cancelInitialization,
    ]
  );

  return <PickingContext.Provider value={value}>{children}</PickingContext.Provider>;
};

export const usePickingSession = () => {
  const context = useContext(PickingContext);
  if (!context) {
    throw new Error('usePickingSession must be used within a PickingProvider');
  }
  return context;
};

import { createContext, useContext, useState, useEffect, ReactNode } from 'react';

type Theme = 'light' | 'dark';

interface ThemeContextType {
  theme: Theme;
  setTheme: (theme: Theme) => void;
  toggleTheme: () => void;
}

const ThemeContext = createContext<ThemeContextType | undefined>(undefined);

export const ThemeProvider = ({ children }: { children: ReactNode }) => {
  const [theme, setTheme] = useState<Theme>(() => {
    try {
      const savedTheme = localStorage.getItem('theme');
      if (savedTheme) {
        const cleaned = savedTheme.replace(/^"(.*)"$/, '$1') as Theme;
        if (cleaned === 'light' || cleaned === 'dark') return cleaned;
        return savedTheme as Theme;
      }
    } catch (e) {
      console.error('Error reading theme from localStorage', e);
    }

    if (window.matchMedia('(prefers-color-scheme: dark)').matches) {
      return 'dark';
    }

    return 'light';
  });

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
    document.documentElement.style.colorScheme = theme;

    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }

    localStorage.setItem('theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme((prev) => (prev === 'light' ? 'dark' : 'light'));
  };

  return (
    <ThemeContext.Provider value={{ theme, setTheme, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  );
};

export const useTheme = () => {
  const context = useContext(ThemeContext);
  if (!context) {
    throw new Error('useTheme must be used within a ThemeProvider');
  }
  return context;
};

