  const requestStockView = useCallback(() => {
    setViewMode('stock');
    setStockNavSignal((n) => n + 1);
  }, []);

  const value = useMemo(
    () => ({
      viewMode,
      setViewMode,
      externalDoubleCheckId,
      setExternalDoubleCheckId,
