import { useMemo, useEffect, useCallback } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { supabase } from '../../../lib/supabase';

// Define the shape of items in the JSONB column
// We assume it's an array of items with at least some basic properties
export interface PickingItem {
  sku: string;
  qty: number;
  location?: string;
  [key: string]: string | number | boolean | null | undefined;
}

export interface Profile {
  full_name: string | null;
}

export interface OrderGroup {
  id: string;
  group_type: string;
}

export interface PickingList {
  id: string;
  order_number: string;
  status:
    | 'active'
    | 'ready_to_double_check'
    | 'double_checking'
    | 'needs_correction'
    | 'completed'
    | 'cancelled';
  items: PickingItem[];
  updated_at: string;
  user_id: string;
  checked_by: string | null;
  profiles?: Profile | null; // Joined profile
  checker_profile?: Profile | null; // Joined checker profile
  customer?: { name: string } | null;
  source?: string;
  is_addon?: boolean;
  group_id?: string | null;
  order_group?: OrderGroup | null;
  is_waiting_inventory?: boolean;
  waiting_reason?: string | null;
  shipping_type?: string | null;
  pallets_qty?: number | null;
  total_units?: number | null;
  source_order_date?: string | null;
  transport_company?: string | null;
  is_shipped?: boolean;
  verified_item_keys?: string[] | null;
}

const PICKING_LIST_SELECT = `
  id,
  order_number,
  status,
  items,
  updated_at,
  user_id,
  checked_by,
  profiles!user_id (full_name),
  checker_profile:profiles!checked_by (full_name),
  customer:customers(name),
  source,
  is_addon,
  group_id,
  order_group:order_groups(id, group_type),
  is_waiting_inventory,
  waiting_reason,
  shipping_type,
  pallets_qty,
  total_units,
  source_order_date,
  transport_company,
  is_shipped,
  verified_item_keys
`;

export const VERIFICATION_QUEUE_KEY = ['picking_lists', 'verification_queue'];
export const COMPLETED_ORDERS_KEY = ['picking_lists', 'completed_recent'];

export const useDoubleCheckList = () => {
  const queryClient = useQueryClient();

  const { data: rawOrders, isLoading: ordersLoading } = useQuery<PickingList[]>({
    queryKey: VERIFICATION_QUEUE_KEY,
    queryFn: async () => {
      const { data, error } = await (
        supabase.from('picking_lists').select(PICKING_LIST_SELECT) as any
      )
        .in('status', ['active', 'ready_to_double_check', 'double_checking', 'needs_correction'])
        .or('is_shipped.is.null,is_shipped.eq.false')
        .order('updated_at', { ascending: false });

      if (error) throw error;
      // Active orders are always shown (even with empty items) so manually-created
      // orders are visible. Other statuses still require items to be present.
      return ((data ?? []) as PickingList[]).filter(
        (o) => o.status === 'active' || (o.items && Array.isArray(o.items) && o.items.length > 0)
      );
    },
    staleTime: 5_000,
    refetchOnWindowFocus: false,
  });

  const { data: completedOrders, isLoading: completedLoading } = useQuery<PickingList[]>({
    queryKey: COMPLETED_ORDERS_KEY,
    queryFn: async () => {
      const { data, error } = await (
        supabase.from('picking_lists').select(PICKING_LIST_SELECT) as any
      )
        .eq('status', 'completed')
        .or('is_shipped.is.null,is_shipped.eq.false')
        .order('updated_at', { ascending: false })
        // Wide enough to cover a full day's completions; the board splits
        // "today" vs "recent" client-side (recent shows with date labels
        // when the board has no active orders).
        .limit(30);

      if (error) throw error;
      return (data as PickingList[]) || [];
    },
    staleTime: 5_000,
    refetchOnWindowFocus: false,
  });

  // Realtime subscription — invalidate queries on changes
  // Unique channel name per mount to avoid stale channel conflicts on re-open
  useEffect(() => {
    const channelName = `picking_lists_queue_${Date.now()}`;
    const channel = supabase
      .channel(channelName)
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'picking_lists',
        },
        () => {
          queryClient.invalidateQueries({ queryKey: VERIFICATION_QUEUE_KEY });
          queryClient.invalidateQueries({ queryKey: COMPLETED_ORDERS_KEY });
        }
      )
      .subscribe((status) => {
        if (status === 'SUBSCRIBED') {
          console.log(`✅ [VerificationQueue] Realtime subscribed: ${channelName}`);
        } else if (status === 'CHANNEL_ERROR' || status === 'TIMED_OUT') {
          console.error(`❌ [VerificationQueue] Realtime ${status}: ${channelName}`);
        }
      });

    return () => {
      supabase.removeChannel(channel);
    };
  }, [queryClient]);

  const orders = rawOrders ?? [];

  const { readyCount, correctionCount, checkingCount, waitingCount } = useMemo(
    () => ({
      readyCount: orders.filter(
        (o) => o.status === 'ready_to_double_check' && !o.is_waiting_inventory
      ).length,
      correctionCount: orders.filter(
        (o) => o.status === 'needs_correction' && !o.is_waiting_inventory
      ).length,
      checkingCount: orders.filter((o) => o.status === 'double_checking' && !o.is_waiting_inventory)
        .length,
      waitingCount: orders.filter((o) => o.is_waiting_inventory).length,
    }),
    [orders]
  );

  const refresh = useCallback(() => {
    queryClient.invalidateQueries({ queryKey: VERIFICATION_QUEUE_KEY });
    queryClient.invalidateQueries({ queryKey: COMPLETED_ORDERS_KEY });
  }, [queryClient]);

  return {
    orders,
    completedOrders: completedOrders ?? [],
    readyCount,
    correctionCount,
    checkingCount,
    waitingCount,
    loading: ordersLoading || completedLoading,
    refresh,
  };
};

import React, { useCallback } from 'react';
import toast from 'react-hot-toast';
import { supabase } from '../../../lib/supabase';
import type { CartItem } from './usePickingCart';
import type { Customer } from '../../../types/schema';
import {
  getOptimizedPickingPath,
  calculatePalletsWithBikeAwareness,
  type PickingItem,
} from '../../../utils/pickingLogic';
import { resolveBikeSkuSet } from '../../../utils/bikeDetection';
import type { User } from '@supabase/supabase-js';
import type { Json } from '../../../integrations/supabase/types';
import type { Location } from '../../../schemas/location.schema';

/** Shape for stock tracking with reservation info */
interface StockEntry {
  stock: number;
  reserved: number;
  reservingOrders: Set<string>;
}

/** Shape returned by the inventory select query */
interface InventoryRow {
  sku: string;
  quantity: number;
  warehouse: string;
  location: string | null;
}

/** Shape returned by the picking_lists select query (partial) */
interface PickingListRow {
  id: string;
  items: CartItem[] | null;
  order_number: string | null;
}

/** Shape returned by picking_list status query */
interface PickingListStatusRow {
  status: string | null;
  notes?: string | null;
}

interface UsePickingActionsProps {
  user: User | null;
  activeListId: string | null;
  cartItems: CartItem[];
  orderNumber: string | null;
  customer: Customer | null;
  sessionMode: 'picking' | 'double_checking' | 'idle' | 'reopened';
  setCartItems: (items: CartItem[]) => void;
  setActiveListId: (id: string | null) => void;
  setOrderNumber: (num: string | null) => void;
  setCustomer: (cust: Customer | null) => void;
  setListStatus: (status: string) => void;
  setCheckedBy: (id: string | null) => void;
  setOwnerId: (id: string | null) => void;
  ownerId: string | null;
  loadNumber: string | null;
  setLoadNumber: (num: string | null) => void;
  setCorrectionNotes: (notes: string | null) => void;
  setSessionMode: (mode: 'picking' | 'double_checking' | 'reopened') => void;
  setIsSaving: (val: boolean) => void;
  resetSession: (skipState?: boolean) => void;
  isInWorkflowRef: React.MutableRefObject<boolean>;
}

export const usePickingActions = ({
  user,
  activeListId,
  cartItems,
  orderNumber,
  customer,
  setCartItems,
  setActiveListId,
  setOrderNumber,
  setCustomer,
  setListStatus,
  setCheckedBy,
  setOwnerId,
  ownerId,
  setCorrectionNotes,
  setSessionMode,
  setIsSaving,
  resetSession,
  loadNumber,
  isInWorkflowRef,
}: UsePickingActionsProps) => {
  const completeList = useCallback(
    async (metrics?: { pallets_qty: number; total_units: number }, listIdOverride?: string) => {
      const targetId = listIdOverride || activeListId;

      if (!targetId || !user) return;
      setIsSaving(true);
      try {
        const updateData: {
          status: string;
          checked_by: string;
          pallets_qty?: number;
          total_units?: number;
          is_waiting_inventory?: boolean;
        } = {
          status: 'completed',
          checked_by: user.id, // Record who verified it
          is_waiting_inventory: false,
        };

        if (metrics) {
          updateData.pallets_qty = metrics.pallets_qty;
          updateData.total_units = metrics.total_units;
        }

        const { error } = await supabase
          .from('picking_lists')
          .update(updateData)
          .eq('id', targetId);

        if (error) throw error;

        // Persist shipping_type if not already set
        const { data: currentList } = await supabase
          .from('picking_lists')
          .select('shipping_type, items')
          .eq('id', targetId)
          .single();

        if (currentList && !currentList.shipping_type) {
          const items = (currentList.items as unknown as CartItem[]) || [];
          const totalItems = items.reduce((sum, i) => sum + (i.pickingQty || 0), 0);
          const autoType = totalItems >= 5 ? 'regular' : 'fedex';
          await supabase
            .from('picking_lists')
            .update({ shipping_type: autoType })
            .eq('id', targetId);
        }
      } catch (err) {
        console.error('Failed to complete list:', err);
        toast.error('Failed to complete order properly');
        throw err;
      } finally {
        setIsSaving(false);
      }
    },
    [activeListId, user, setIsSaving]
  );

  const markAsReady = useCallback(
    async (items?: CartItem[], orderNum?: string) => {
      if (!activeListId || !user) return null;

      const finalItems = items || cartItems;
      const finalOrderNum = orderNum || orderNumber;

      if (finalItems.length === 0) {
        toast.error('Cannot mark an empty order as ready.');
        return null;
      }

      setIsSaving(true);
      try {
        // Enforcement: Release any other list this user might be checking
        const { error: releaseError } = await supabase
          .from('picking_lists')
          .update({
            status: 'ready_to_double_check',
            checked_by: null,
          })
          .eq('checked_by', user.id)
          .neq('status', 'completed')
          .neq('status', 'cancelled')
          .neq('id', activeListId); // Don't release the one we are about to lock

        if (releaseError) console.error('Error releasing previous locks:', releaseError);

        // 1. Validation Logic: Check for concurrency conflicts
        // We must ensure that (Stock - ReservedByOthers) >= MyQty
        const skuList = finalItems.map((i) => i.sku);

        // A. Fetch current stock
        const { data: currentStock, error: stockError } = await supabase
          .from('inventory')
          .select('sku, quantity, warehouse, location')
          .in('sku', skuList);

        if (stockError) throw stockError;

        // NEW: Fetch locations picking order for optimization
        const locationsToFetch = Array.from(
          new Set(finalItems.map((i) => i.location).filter((loc): loc is string => !!loc))
        );
        const { data: locationsData, error: locsError } = await supabase
          .from('locations')
          .select('warehouse, location, picking_order')
          .in('location', locationsToFetch);

        if (locsError) console.error('Error fetching picking orders:', locsError);

        // B. Fetch ALL active allocations for these SKUs (excluding self)
        const { data: activeLists, error: listsError } = await supabase
          .from('picking_lists')
          .select('id, items, order_number')
          .in('status', ['active', 'needs_correction', 'ready_to_double_check', 'double_checking'])
          .neq('id', activeListId);

        if (listsError) throw listsError;

        // C. Calculate availability
        const stockMap = new Map<string, StockEntry>();

        // Fill stock
        (currentStock as InventoryRow[] | null)?.forEach((row) => {
          const key = `${row.sku}-${row.warehouse}-${(row.location || '').toUpperCase()}`;
          stockMap.set(key, {
            stock: Number(row.quantity || 0),
            reserved: 0,
            reservingOrders: new Set(),
          });
        });

        // Fill reservations
        (activeLists as PickingListRow[] | null)?.forEach((list) => {
          const listItems = list.items || [];
          if (Array.isArray(listItems)) {
            listItems.forEach((li: CartItem) => {
              const key = `${li.sku}-${li.warehouse}-${(li.location || '').toUpperCase()}`;
              if (stockMap.has(key)) {
                const entry = stockMap.get(key)!;
                entry.reserved += li.pickingQty || 0;
                if (list.order_number) entry.reservingOrders.add(list.order_number);
              }
            });
          }
        });

        // D. Validate my cart
        for (const myItem of finalItems) {
          // Unregistered / unresolved items must not block parking or finishing.
          // They have no reliable inventory row to reserve against, so skip the
          // availability gate here and let the correction/completion flow handle
          // them operationally.
          if (myItem.sku_not_found || !myItem.warehouse || !myItem.location) {
            continue;
          }

          const key = `${myItem.sku}-${myItem.warehouse}-${(myItem.location || '').toUpperCase()}`;
          const entry = stockMap.get(key);

          // If a previously registered inventory-backed item disappeared, fail.
          if (!entry) {
            toast.error(`Item ${myItem.sku} no longer exists in inventory.`);
            return null;
          }

          const availableForMe = entry.stock - entry.reserved;
          const myQty = myItem.pickingQty || 0;

          if (myQty > availableForMe) {
            const orders = Array.from(entry.reservingOrders).join(', ');
            const reservedInfo = orders ? `is reserved in ${orders}.` : 'is reserved.';
            const availabilityInfo =
              availableForMe > 0
                ? `There is only ${availableForMe} available.`
                : 'There are no more items available.';

            toast.error(`${myItem.sku} ${reservedInfo} ${availabilityInfo} (You need ${myQty}).`, {
              duration: 6000,
            });
            return null; // Abort
          }
        }
        // --- End Validation ---

        // Calculate Pallets using the same logic as UI
        const optimizedItems = getOptimizedPickingPath(
          finalItems as unknown as PickingItem[],
          (locationsData as Location[]) || []
        );
        const bikeSkuSet = await resolveBikeSkuSet(optimizedItems.map((i) => i.sku));
        const pallets = calculatePalletsWithBikeAwareness(optimizedItems, bikeSkuSet);
        const palletsQty = pallets.length;

        // Transition to double_checking immediately
        // Guard: never write merged group data back — merged order_numbers contain ' / '
        const isMergedGroup = finalOrderNum?.includes(' / ');
        const updateData: Record<string, unknown> = {
          status: 'double_checking',
          checked_by: user.id,
          customer_id: customer?.id,
          load_number: loadNumber,
          correction_notes: null,
          pallets_qty: palletsQty,
        };
        if (!isMergedGroup) {
          updateData.items = finalItems as unknown as Json;
          updateData.order_number = finalOrderNum;
        }
        const { error } = await supabase
          .from('picking_lists')
          .update(updateData)
          .eq('id', activeListId);

        if (error) throw error;

        const listId = activeListId;
        setCartItems(finalItems);
        setOrderNumber(finalOrderNum); // Ensure local state matches
        setCorrectionNotes(null);
        setListStatus('double_checking');
        setCheckedBy(user.id);
        setSessionMode('double_checking');
        toast.success('Order ready! You can now verify it.');
        return listId;
      } catch (err: unknown) {
        console.error('Failed to mark as ready:', err);
        toast.error('Failed to mark order ready');
        return null;
      } finally {
        setIsSaving(false);
      }
    },
    [
      activeListId,
      user,
      cartItems,
      orderNumber,
      customer,
      loadNumber,
      setCartItems,
      setOrderNumber,
      setCorrectionNotes,
      setListStatus,
      setCheckedBy,
      setSessionMode,
      setIsSaving,
    ]
  );

  const lockForCheck = useCallback(
    async (listId: string) => {
      if (!user) return;
      const { error: releaseError } = await supabase
        .from('picking_lists')
        .update({
          status: 'ready_to_double_check',
          checked_by: null,
        })
        .eq('checked_by', user.id)
        .neq('status', 'completed')
        .neq('status', 'cancelled')
        .neq('id', listId);

      if (releaseError) console.error('Error releasing previous locks:', releaseError);

      // Query order metadata to check group and owner
      const { data: order } = await supabase
        .from('picking_lists')
        .select(
          `
          group_id,
          user_id,
          profiles!user_id (full_name)
        `
        )
        .eq('id', listId)
        .maybeSingle();

      const shouldClaim = (order as any)?.profiles?.full_name === 'Warehouse Team';

      // Lock the main order
      const updateFields: any = {
        status: 'double_checking',
        checked_by: user.id,
      };
      if (shouldClaim) {
        updateFields.user_id = user.id;
      }

      const { error } = await supabase
        .from('picking_lists')
        .update(updateFields)
        .eq('id', listId)
        .neq('status', 'completed');
      if (error) throw error;

      // If order belongs to a group, also lock all siblings
      if (order?.group_id) {
        await supabase
          .from('picking_lists')
          .update({
            status: 'double_checking',
            checked_by: user.id,
          })
          .eq('group_id', order.group_id)
          .neq('id', listId)
          .neq('status', 'completed')
          .neq('status', 'cancelled');

        // Claim any group sibling still owned by Warehouse Team (Warehouse Team Profile ID: 38f493d0-1385-4d12-940c-56dffe10de7e)
        await supabase
          .from('picking_lists')
          .update({ user_id: user.id })
          .eq('group_id', order.group_id)
          .eq('user_id', '38f493d0-1385-4d12-940c-56dffe10de7e')
          .neq('status', 'completed')
          .neq('status', 'cancelled');
      }
    },
    [user]
  );

  // Park: release the lock without transitioning status. Used when the
  // verifier wants to leave a half-checked order back in its lane (FedEx /
  // Regular) so any teammate can pick it up — distinct from releaseCheck,
  // which sends the order to the Ready-to-Double-Check queue.
  const parkOrder = useCallback(
    async (listId: string) => {
      const { data: order } = await supabase
        .from('picking_lists')
        .select('group_id')
        .eq('id', listId)
        .single();

      const { error } = await supabase
        .from('picking_lists')
        .update({ checked_by: null, updated_at: new Date().toISOString() })
        .eq('id', listId)
        .neq('status', 'completed')
        .neq('status', 'cancelled');
      if (error) throw error;

      if (order?.group_id) {
        await supabase
          .from('picking_lists')
          .update({ checked_by: null, updated_at: new Date().toISOString() })
          .eq('group_id', order.group_id)
          .neq('id', listId)
          .neq('status', 'completed')
          .neq('status', 'cancelled');
      }

      resetSession();
    },
    [resetSession]
  );

  const releaseCheck = useCallback(
    async (listId: string) => {
      // Check if order belongs to a group — release all siblings too
      const { data: order } = await supabase
        .from('picking_lists')
        .select('group_id')
        .eq('id', listId)
        .single();

      const { error } = await supabase
        .from('picking_lists')
        .update({
          status: 'ready_to_double_check',
          checked_by: null,
        })
        .eq('id', listId)
        .neq('status', 'completed');
      if (error) throw error;

      if (order?.group_id) {
        await supabase
          .from('picking_lists')
          .update({
            status: 'ready_to_double_check',
            checked_by: null,
          })
          .eq('group_id', order.group_id)
          .neq('id', listId)
          .neq('status', 'completed')
          .neq('status', 'cancelled');
      }

      resetSession();
    },
    [resetSession]
  );

  const returnToPicker = useCallback(
    async (listId: string, notes: string) => {
      if (!user) {
        console.error('No user found for returnToPicker');
        return;
      }

      try {
        // 1. Update list status (deprecating legacy notes column)
        const { error: listError } = await supabase
          .from('picking_lists')
          .update({
            status: 'needs_correction',
            checked_by: null,
          })
          .eq('id', listId)
          .neq('status', 'completed');

        if (listError) throw listError;

        // 2. Release group siblings so they go back to the queue
        const { data: order } = await supabase
          .from('picking_lists')
          .select('group_id')
          .eq('id', listId)
          .single();

        if (order?.group_id) {
          await supabase
            .from('picking_lists')
            .update({
              status: 'ready_to_double_check',
              checked_by: null,
            })
            .eq('group_id', order.group_id)
            .neq('id', listId)
            .neq('status', 'completed')
            .neq('status', 'cancelled');
        }

        // 3. Add to historical notes timeline
        const { error: noteError } = await supabase.from('picking_list_notes').insert({
          list_id: listId,
          user_id: user.id,
          message: notes,
        });

        if (noteError) {
          console.error('Failed to log historical note:', noteError);
        }

        // Clear local state
        resetSession();
        toast.success('Sent back to picker.');
      } catch (err) {
        console.error('Failed to return to picker:', err);
        toast.error('Failed to update order status');
      }
    },
    [user, resetSession]
  );

  const revertToPicking = useCallback(async () => {
    if (!activeListId || !user) return;
    setIsSaving(true);
    try {
      const { error } = await supabase
        .from('picking_lists')
        .update({
          status: 'active',
          checked_by: null,
        })
        .eq('id', activeListId);

      if (error) throw error;

      setListStatus('active');
      setCheckedBy(null);
      setSessionMode('picking');
      toast.success('Returned to picking mode.');
    } catch (err) {
      console.error('Failed to revert to picking:', err);
    } finally {
      setIsSaving(false);
    }
  }, [activeListId, user, setListStatus, setCheckedBy, setSessionMode, setIsSaving]);

  const deleteList = useCallback(
    async (listId: string | null, keepLocalState = false) => {
      if (!listId) {
        if (!keepLocalState) resetSession();
        toast.success('Local session reset');
        return;
      }

      try {
        const { data: currentList } = await supabase
          .from('picking_lists')
          .select('status, group_id')
          .eq('id', listId)
          .maybeSingle();

        // Completed/reopened: restore inventory + mark cancelled via RPC.
        // The RPC is idempotent and handles the reopen-revert + group cleanup.
        if (currentList?.status === 'completed' || currentList?.status === 'reopened') {
          const { data, error: rpcError } = await supabase.rpc('cancel_completed_order', {
            p_list_id: listId,
            p_user_id: user?.id ?? null,
          });

          if (rpcError) {
            console.error('cancel_completed_order failed:', rpcError);
            toast.error('Failed to cancel order: ' + rpcError.message);
            throw rpcError;
          }

          const result =
            (data as {
              restored_units?: number;
              items_restored?: number;
              already_cancelled?: boolean;
            } | null) ?? {};
          if (result.already_cancelled) {
            toast('Order was already cancelled', { icon: 'ℹ️' });
          } else {
            toast.success(
              `Order cancelled — ${result.restored_units ?? 0} units restored to inventory`
            );
          }

          if (listId === activeListId && !keepLocalState) {
            resetSession();
          }
          return;
        }

        // If the order is already in picking/verification, we should probably CANCEL it
        // instead of physically deleting it, to keep a record.
        const inProgressStatuses = [
          'active',
          'ready_to_double_check',
          'double_checking',
          'needs_correction',
        ];
        if (currentList?.status && inProgressStatuses.includes(currentList.status)) {
          // Instead of hard delete, we mark as cancelled
          const typedList = currentList as PickingListStatusRow;
          const { error: cancelError } = await supabase
            .from('picking_lists')
            .update({
              status: 'cancelled',
              notes: typedList.notes ? typedList.notes + ' [User Cancelled]' : 'User Cancelled',
            })
            .eq('id', listId);

          if (cancelError) throw cancelError;

          // Cleanup group if order belonged to one
          if (currentList.group_id) {
            const { data: remaining } = await supabase
              .from('picking_lists')
              .select('id')
              .eq('group_id', currentList.group_id)
              .neq('status', 'cancelled')
              .neq('id', listId)
              .limit(2);

            if (remaining && remaining.length <= 1) {
              // Dissolve group: unlink last remaining order and delete group
              if (remaining.length === 1) {
                await supabase
                  .from('picking_lists')
                  .update({ group_id: null })
                  .eq('id', remaining[0].id);
              }
              await supabase.from('order_groups').delete().eq('id', currentList.group_id);
            }
          }

          if (listId === activeListId && !keepLocalState) {
            resetSession();
          }
          toast.success('Order cancelled and moved to history');
          return;
        }

        // Cleanup group before hard delete
        if (currentList?.group_id) {
          const { data: remaining } = await supabase
            .from('picking_lists')
            .select('id')
            .eq('group_id', currentList.group_id)
            .neq('id', listId)
            .limit(2);

          if (remaining && remaining.length <= 1) {
            if (remaining.length === 1) {
              await supabase
                .from('picking_lists')
                .update({ group_id: null })
                .eq('id', remaining[0].id);
            }
            await supabase.from('order_groups').delete().eq('id', currentList.group_id);
          }
        }

        const { error: logsError } = await supabase
          .from('inventory_logs')
          .delete()
          .eq('list_id', listId);

        if (logsError) {
          console.error('Failed to delete related inventory logs:', logsError);
          throw logsError;
        }

        const { error } = await supabase.from('picking_lists').delete().eq('id', listId);

        if (error) throw error;

        if (listId === activeListId && !keepLocalState) {
          resetSession();
        }
        if (!keepLocalState) {
          toast.success('Order deleted successfully');
        }
      } catch (err) {
        console.error('Failed to delete list:', err);
        toast.error('Failed to delete order');
        throw err;
      }
    },
    [activeListId, resetSession, user]
  );

  const generatePickingPath = useCallback(async () => {
    if (!user || cartItems.length === 0) {
      toast.error('Add items to your cart first.');
      return;
    }
    isInWorkflowRef.current = true;

    setIsSaving(true);
    try {
      const skuList = cartItems.map((i) => i.sku);

      const { data: currentStock, error: stockError } = await supabase
        .from('inventory')
        .select('sku, quantity, warehouse, location, sublocation')
        .in('sku', skuList);

      if (stockError) throw stockError;

      const { data: activeLists, error: listsError } = await supabase
        .from('picking_lists')
        .select('id, items, order_number')
        .in('status', ['active', 'needs_correction', 'ready_to_double_check', 'double_checking']);

      if (listsError) throw listsError;

      const stockMap = new Map<string, StockEntry>();

      (currentStock as InventoryRow[] | null)?.forEach((row) => {
        const key = `${row.sku}-${row.warehouse}-${row.location}`;
        stockMap.set(key, {
          stock: Number(row.quantity || 0),
          reserved: 0,
          reservingOrders: new Set(),
        });
      });

      (activeLists as PickingListRow[] | null)?.forEach((list) => {
        // Skip our own list when recalculating reservations (bug-004: we're updating it, not adding a new one)
        if (activeListId && list.id === activeListId) return;
        const listItems = list.items || [];
        if (Array.isArray(listItems)) {
          listItems.forEach((li: CartItem) => {
            const key = `${li.sku}-${li.warehouse}-${li.location}`;
            if (stockMap.has(key)) {
              const entry = stockMap.get(key)!;
              entry.reserved += li.pickingQty || 0;
              if (list.order_number) entry.reservingOrders.add(list.order_number);
            }
          });
        }
      });

      for (const myItem of cartItems) {
        const key = `${myItem.sku}-${myItem.warehouse}-${myItem.location}`;
        const entry = stockMap.get(key);

        if (!entry) {
          toast.error(`Item ${myItem.sku} no longer exists in inventory.`);
          return;
        }

        const availableAcrossSystem = entry.stock - entry.reserved;
        const myQty = myItem.pickingQty || 0;

        if (myQty > availableAcrossSystem) {
          const orders = Array.from(entry.reservingOrders).join(', ');
          const reservedInfo = orders ? `is reserved in ${orders}.` : 'is reserved.';
          const availabilityInfo =
            availableAcrossSystem > 0
              ? `There is only ${availableAcrossSystem} available.`
              : 'There are no more items available.';

          toast.error(`${myItem.sku} ${reservedInfo} ${availabilityInfo} (You need ${myQty}).`, {
            duration: 6000,
          });
          return;
        }
      }

      // Ensure customer exists if it's a new one (name only)
      let customerId = customer?.id;
      if (!customerId && customer?.name) {
        const normalizedName = customer.name.trim();

        // 1. Try to find existing customer by name first
        const { data: existing } = await supabase
          .from('customers')
          .select('id')
          .eq('name', normalizedName)
          .maybeSingle();

        if (existing) {
          customerId = existing.id;
        } else {
          // 2. Create new customer if not found
          const { data: newCust, error: createError } = await supabase
            .from('customers')
            .insert({ name: normalizedName })
            .select('id')
            .single();

          if (createError) {
            console.error('Failed to create customer:', createError);
            throw createError;
          }
          customerId = newCust.id;
        }
      }

      // bug-004 fix: UPDATE existing record when returning from double-check, INSERT only for new sessions
      let data: { id: string; user_id: string } | null;
      let error: { message: string; code?: string } | null;

      if (activeListId) {
        // Reuse existing picking_list record (user returned from double-check to correct items)
        // Guard (mirrors dd64e78): never write merged group / watchdog-combined
        // data back to DB. Merged order_numbers contain ' / ' (e.g.
        // "879484 / 879460"). Local cartItems can lag behind the DB after a
        // watchdog combine (realtime only syncs metadata), so writing the
        // local snapshot here would silently delete items the watchdog merged.
        // Order 879460 lost 11 items on 2026-04-30 through this exact path.
        const isMergedGroup = orderNumber?.includes(' / ');
        const updateData: Record<string, unknown> = {
          status: 'active',
          customer_id: customerId,
          load_number: loadNumber,
        };
        if (!isMergedGroup) {
          updateData.items = cartItems as unknown as Json;
          updateData.order_number = orderNumber;
        }
        const result = await supabase
          .from('picking_lists')
          .update(updateData)
          .eq('id', activeListId)
          .select()
          .single();
        data = result.data as { id: string; user_id: string } | null;
        error = result.error;
      } else {
        const result = await supabase
          .from('picking_lists')
          .insert({
            user_id: user.id,
            items: cartItems as unknown as Json,
            status: 'active',
            order_number: orderNumber,
            customer_id: customerId,
            load_number: loadNumber,
          })
          .select()
          .single();
        data = result.data as { id: string; user_id: string } | null;
        error = result.error;
      }

      if (error) throw error;

      if (data) {
        setActiveListId(data.id);
        const resolvedOwnerId = data.user_id;
        setListStatus('active');
        setOwnerId(resolvedOwnerId);
        setSessionMode('picking');

        // CRITICAL FIX: Update local customer state with the RESOLVED ID so the UI knows it's real
        if (customerId && customer?.name) {
          setCustomer({
            ...customer,
            id: customerId,
            name: customer.name.trim(), // Ensure consistent trimming
          });
        }

        localStorage.setItem('picking_session_mode', 'picking');
        localStorage.setItem('active_picking_list_id', data.id);

        toast.success('Path generated! Stock reserved.');
      }
    } catch (err) {
      console.error('Failed to generate picking path:', err);
      toast.error('Failed to start picking session.');
    } finally {
      isInWorkflowRef.current = false;
      setIsSaving(false);
    }
  }, [
    user,
    activeListId,
    cartItems,
    orderNumber,
    customer,
    loadNumber,
    setCustomer,
    setActiveListId,
    setListStatus,
    setOwnerId,
    setSessionMode,
    setIsSaving,
    isInWorkflowRef,
  ]);

  const updateCustomerDetails = useCallback(
    async (customerId: string, details: Partial<Customer>) => {
      try {
        const { error } = await supabase.from('customers').update(details).eq('id', customerId);

        if (error) throw error;

        // Update local state if it's the current customer
        if (customer && customer.id === customerId) {
          setCustomer({ ...customer, ...details });
        }

        toast.success('Customer details updated');
      } catch (err) {
        console.error('Failed to update customer details:', err);
        toast.error('Failed to update customer details');
        throw err;
      }
    },
    [customer, setCustomer]
  );

  // Claim the order as picker if the current owner is "Warehouse Team" (script account)
  const claimAsPicker = useCallback(
    async (listIdOverride?: string) => {
      const targetId = listIdOverride || activeListId;
      if (!targetId || !user) return;

      // Already the owner — nothing to claim
      if (ownerId === user.id) return;

      // Check if the current owner is the script account ("Warehouse Team")
      if (ownerId) {
        const { data: ownerProfile } = await supabase
          .from('profiles')
          .select('full_name')
          .eq('id', ownerId)
          .single();

        if (ownerProfile?.full_name !== 'Warehouse Team') return;
      }

      // Claim: update user_id to the current user
      const { error } = await supabase
        .from('picking_lists')
        .update({ user_id: user.id })
        .eq('id', targetId);

      if (error) {
        console.error('Failed to claim order as picker:', error);
        return;
      }

      setOwnerId(user.id);
    },
    [activeListId, user, ownerId, setOwnerId]
  );

  const takeOverOrder = useCallback(
    async (listId: string) => {
      if (!user) return;
      setIsSaving(true);
      try {
        const now = new Date().toISOString();
        const { error } = await supabase
          .from('picking_lists')
          .update({
            user_id: user.id,
            last_activity_at: now,
            updated_at: now,
          })
          .eq('id', listId);

        if (error) throw error;

        toast.success('You have taken over this order.');
      } catch (err) {
        console.error('Failed to take over order:', err);
        toast.error('Failed to take over order');
        throw err; // Rethrow so callers (handleContinueEditing) can abort
      } finally {
        setIsSaving(false);
      }
    },
    [user, setIsSaving]
  );

  // ============================================================
  // Reopen Completed Orders
  // ============================================================

  const reopenOrder = useCallback(
    async (listId: string, reason?: string) => {
      if (!user) return;
      setIsSaving(true);
      try {
        const { error } = await supabase.rpc('reopen_picking_list', {
          p_list_id: listId,
          p_reopened_by: user.id,
          p_reason: reason ?? undefined,
        });
        if (error) throw error;
        toast.success('Order reopened for editing');
      } catch (err) {
        console.error('Failed to reopen order:', err);
        toast.error(err instanceof Error ? err.message : 'Failed to reopen order');
        throw err;
      } finally {
        setIsSaving(false);
      }
    },
    [user, setIsSaving]
  );

  const restoreCancelledOrder = useCallback(
    async (listId: string, reason?: string) => {
      if (!user) return;
      setIsSaving(true);
      try {
        const { error } = await supabase.rpc('restore_cancelled_order', {
          p_list_id: listId,
          p_restored_by: user.id,
          p_reason: reason ?? undefined,
        });
        if (error) throw error;
        toast.success('Order restored');
      } catch (err) {
        console.error('Failed to restore order:', err);
        toast.error(err instanceof Error ? err.message : 'Failed to restore order');
        throw err;
      } finally {
        setIsSaving(false);
      }
    },
    [user, setIsSaving]
  );

  const recompleteOrder = useCallback(
    async (listId: string, palletsQty: number, totalUnits: number) => {
      if (!user) return;
      setIsSaving(true);
      try {
        const { data: profile } = await supabase
          .from('profiles')
          .select('full_name, role')
          .eq('id', user.id)
          .single();

        const { error } = await supabase.rpc('recomplete_picking_list', {
          p_list_id: listId,
          p_performed_by: profile?.full_name || user.email || 'Unknown',
          p_user_id: user.id,
          p_pallets_qty: palletsQty,
          p_total_units: totalUnits,
          p_user_role: profile?.role || 'staff',
        });
        if (error) throw error;
        toast.success('Order re-completed successfully');
        resetSession();
      } catch (err) {
        console.error('Failed to re-complete order:', err);
        toast.error(err instanceof Error ? err.message : 'Failed to re-complete order');
        throw err;
      } finally {
        setIsSaving(false);
      }
    },
    [user, setIsSaving, resetSession]
  );

  /**
   * idea-067 Phase 2: atomic completion for an Add-On reopen flow. Calls the
   * complete_addon_group RPC which re-completes the source (delta inventory)
   * AND completes the target in a single transaction.
   */
  const completeAddonGroup = useCallback(
    async (
      sourceId: string,
      targetId: string,
      sourcePallets: number,
      sourceUnits: number,
      targetPallets: number,
      targetUnits: number
    ) => {
      if (!user) return;
      setIsSaving(true);
      try {
        const { data: profile } = await supabase
          .from('profiles')
          .select('full_name, role')
          .eq('id', user.id)
          .single();

        const { error } = await supabase.rpc('complete_addon_group', {
          p_source_id: sourceId,
          p_target_id: targetId,
          p_performed_by: profile?.full_name || user.email || 'Unknown',
          p_user_id: user.id,
          p_source_pallets: sourcePallets,
          p_source_units: sourceUnits,
          p_target_pallets: targetPallets,
          p_target_units: targetUnits,
          p_user_role: profile?.role || 'staff',
        });
        if (error) throw error;
        toast.success('Add-On completed');
        resetSession();
      } catch (err) {
        console.error('Failed to complete Add-On:', err);
        toast.error(err instanceof Error ? err.message : 'Failed to complete Add-On');
        throw err;
      } finally {
        setIsSaving(false);
      }
    },
    [user, setIsSaving, resetSession]
  );

  const cancelReopen = useCallback(
    async (listId: string) => {
      if (!user) return;
      setIsSaving(true);
      try {
        const { error } = await supabase.rpc('cancel_reopen', {
          p_list_id: listId,
          p_user_id: user.id,
        });
        if (error) throw error;
        toast.success('Reopen cancelled. Order restored.');
        resetSession();
      } catch (err) {
        console.error('Failed to cancel reopen:', err);
        toast.error(err instanceof Error ? err.message : 'Failed to cancel reopen');
      } finally {
        setIsSaving(false);
      }
    },
    [user, setIsSaving, resetSession]
  );

  return {
    completeList,
    markAsReady,
    lockForCheck,
    releaseCheck,
    parkOrder,
    returnToPicker,
    revertToPicking,
    deleteList,
    generatePickingPath,
    updateCustomerDetails,
    takeOverOrder,
    claimAsPicker,
    reopenOrder,
    restoreCancelledOrder,
    recompleteOrder,
    cancelReopen,
    completeAddonGroup,
  };
};

import React, { useEffect, useRef, useCallback } from 'react';
import { type User } from '@supabase/supabase-js';
import { supabase } from '../../../lib/supabase';
import { withSupabaseRetry } from '../../../lib/supabaseRetry';
import { debounce, type DebouncedFunction } from '../../../utils/debounce';
import toast from 'react-hot-toast';
import type { CartItem } from './usePickingCart';
import type { Customer } from '../../../types/schema';
import type { Json } from '../../../integrations/supabase/types';

interface UsePickingSyncProps {
  user: User | null;
  sessionMode: 'picking' | 'double_checking' | 'idle' | 'reopened';
  cartItems: CartItem[];
  orderNumber: string | null;
  activeListId: string | null;
  listStatus: string;
  correctionNotes: string | null;
  checkedBy: string | null;
  setCartItems: (items: CartItem[]) => void;
  setActiveListId: (id: string | null) => void;
  setOrderNumber: (num: string | null) => void;
  customer: Customer | null;
  setCustomer: (cust: Customer | null) => void;
  loadNumber: string | null;
  setLoadNumber: (num: string | null) => void;
  setListStatus: (status: string) => void;
  setIsWaitingInventory: (val: boolean) => void;
  setShippingType: (val: string | null) => void;
  setCheckedBy: (id: string | null) => void;
  ownerId: string | null;
  setOwnerId: (id: string | null) => void;
  setCorrectionNotes: (notes: string | null) => void;
  setSessionMode: (mode: 'picking' | 'double_checking' | 'reopened') => void;
  loadFromLocalStorage: () => void;
  showError: (title: string, msg: string) => void;
  resetSession: () => void;
  setIsSaving: (val: boolean) => void;
  setIsLoaded: (val: boolean) => void;
  setLastSaved: (val: Date | null) => void;
  isSaving: boolean;
  isLoaded: boolean;
  lastSaved: Date | null;
  isInWorkflowRef: React.MutableRefObject<boolean>;
}

const SYNC_DEBOUNCE_MS = 1000;

export const usePickingSync = ({
  user,
  sessionMode,
  cartItems,
  orderNumber,
  activeListId,
  listStatus,
  correctionNotes,
  checkedBy,
  setCartItems,
  setActiveListId,
  setOrderNumber,
  customer,
  setCustomer,
  loadNumber,
  setLoadNumber,
  setListStatus,
  setIsWaitingInventory,
  setShippingType,
  setCheckedBy,
  ownerId,
  setOwnerId,
  setCorrectionNotes,
  setSessionMode,
  loadFromLocalStorage,
  showError,
  resetSession,
  setIsSaving,
  setIsLoaded,
  setLastSaved,
  isSaving,
  isLoaded,
  lastSaved,
  isInWorkflowRef,
}: UsePickingSyncProps) => {
  // State removed and moved to PickingProvider via props

  // Legacy normalizeItems removed - database migration ensures consistent lowercase schema

  const isInitialSyncRef = useRef(true);
  const isSyncingRef = useRef(false);
  const takeoverSyncRef = useRef<string | null>(null);
  const loadSessionCalledRef = useRef(false);

  const sessionModeRef = useRef(sessionMode);
  const listStatusRef = useRef(listStatus);
  const correctionNotesRef = useRef(correctionNotes);
  const checkedByRef = useRef(checkedBy);
  const ownerIdRef = useRef(ownerId);

  useEffect(() => {
    sessionModeRef.current = sessionMode;
    listStatusRef.current = listStatus;
    correctionNotesRef.current = correctionNotes;
    checkedByRef.current = checkedBy;
    ownerIdRef.current = ownerId;
  }, [sessionMode, listStatus, correctionNotes, checkedBy, ownerId]);

  // 1. Initial Load Logic
  useEffect(() => {
    if (!user) {
      setCartItems([]);
      setActiveListId(null);
      setIsLoaded(true);
      loadSessionCalledRef.current = false;
      return;
    }

    const loadSession = async () => {
      try {
        // Guard: Prevent double execution from React StrictMode
        if (loadSessionCalledRef.current) {
          setIsLoaded(true);
          return;
        }
        loadSessionCalledRef.current = true;

        // Guard: Skip if a workflow (generatePickingPath) is in progress
        if (isInWorkflowRef.current) {
          console.log('⏸️ [loadSession] Skipped — workflow in progress');
          setIsLoaded(true);
          return;
        }

        const FIVE_HOURS_MS = 1000 * 60 * 60 * 5;

        // A. Check for double-check session first (Highest priority)
        // Retry-wrapped: this query runs on every app load and was a
        // common flaky-network failure point (silent — the user sees
        // no order even though one exists).
        const { data: doubleCheckData } = await withSupabaseRetry(
          () =>
            supabase
              .from('picking_lists')
              .select('*, customer:customers(*)')
              .eq('checked_by', user.id)
              .eq('status', 'double_checking')
              .limit(1)
              .maybeSingle(),
          { label: 'usePickingSync.loadDoubleCheck' }
        );

        if (doubleCheckData) {
          const updatedAt = doubleCheckData.updated_at
            ? new Date(doubleCheckData.updated_at).getTime()
            : Date.now();
          const isStale = Date.now() - updatedAt > FIVE_HOURS_MS;

          if (isStale) {
            console.log('🧹 Double check session expired (>5h)');
            await supabase
              .from('picking_lists')
              .update({ status: 'ready_to_double_check', checked_by: null })
              .eq('id', doubleCheckData.id);
            resetSession();
          } else {
            setCartItems((doubleCheckData.items as unknown as CartItem[]) || []);
            setActiveListId(doubleCheckData.id as string);
            setOrderNumber(doubleCheckData.order_number || null);
            setCustomer((doubleCheckData.customer as Customer) || null);
            setLoadNumber(doubleCheckData.load_number || null);
            setListStatus(doubleCheckData.status as string);
            setShippingType(
              ((doubleCheckData as Record<string, unknown>).shipping_type as string | null) ?? null
            );
            setIsWaitingInventory(
              !!(doubleCheckData as Record<string, unknown>).is_waiting_inventory
            );
            setCheckedBy(doubleCheckData.checked_by || null);
            setOwnerId(doubleCheckData.user_id || null);
            setCorrectionNotes(doubleCheckData.correction_notes || null);
            setSessionMode('double_checking');
          }
          setIsLoaded(true);
          return;
        }

        // B. Check for active picking sessions owned by this user
        const { data: pickingData, error } = await withSupabaseRetry(
          () =>
            supabase
              .from('picking_lists')
              .select('*, customer:customers(*)')
              .eq('user_id', user.id)
              .in('status', ['active', 'needs_correction', 'reopened'])
              .order('updated_at', { ascending: false })
              .limit(1)
              .maybeSingle(),
          { label: 'usePickingSync.loadActive' }
        );

        if (error) console.error('Error loading picking session:', error);

        if (pickingData) {
          const updatedAt = pickingData.updated_at
            ? new Date(pickingData.updated_at).getTime()
            : Date.now();
          const isStale = Date.now() - updatedAt > FIVE_HOURS_MS;

          if (isStale) {
            // Stale (>5h since last touch): release the local session so the
            // user doesn't auto-resume, but DO NOT delete the order. Orders
            // can legitimately wait days/weeks/months for inventory and the
            // user expects to pick them up later from the orders list.
            // (Previously this DELETEd the row — caused order 879469 to vanish
            // overnight, 2026-04-30. See idea-099 in BACKLOG.md.)
            //
            // idea-099: when the idle order sits in `needs_correction`, auto-
            // flag it as waiting for inventory so it lands in the Waiting
            // bucket of the Verification Board instead of mixing with active
            // correction work. Admin-only RPC; failure is non-fatal (the order
            // is already safe — it just stays in needs_correction without the
            // waiting flag, which is the previous behavior).
            const isNeedsCorrection = pickingData.status === 'needs_correction';
            const alreadyWaiting = !!(pickingData as Record<string, unknown>).is_waiting_inventory;
            if (isNeedsCorrection && !alreadyWaiting) {
              const { error: markErr } = await supabase.rpc('mark_picking_list_waiting', {
                p_list_id: pickingData.id as string,
                p_reason: 'Auto-flagged: idle from a previous session',
              });
              if (markErr) {
                console.warn(
                  '⚠️ Could not auto-flag idle order as waiting (likely non-admin):',
                  markErr.message
                );
              } else {
                console.log('🕒 Idle needs_correction order auto-flagged as waiting');
              }
            }
            console.log('🧹 Picking session idle (>5h) — releasing local session');
            resetSession();
          } else {
            setCartItems((pickingData.items as unknown as CartItem[]) || []);
            setActiveListId(pickingData.id as string);
            setOrderNumber(pickingData.order_number || null);
            setCustomer((pickingData.customer as Customer) || null);
            setLoadNumber(pickingData.load_number || null);
            setListStatus(pickingData.status as string);
            setShippingType(
              ((pickingData as Record<string, unknown>).shipping_type as string | null) ?? null
            );
            setIsWaitingInventory(!!(pickingData as Record<string, unknown>).is_waiting_inventory);
            setCheckedBy(pickingData.checked_by || null);
            setOwnerId(pickingData.user_id || null);
            setCorrectionNotes(pickingData.correction_notes || null);
            setSessionMode(pickingData.status === 'reopened' ? 'reopened' : 'picking');
          }
        } else {
          // C. Sanitization Check: If user has an ID in localStorage but no valid session in DB
          const localId = localStorage.getItem('active_picking_list_id');
          if (localId) {
            const { data: remoteCheck } = await supabase
              .from('picking_lists')
              .select('status')
              .eq('id', localId)
              .maybeSingle();

            if (
              !remoteCheck ||
              remoteCheck.status === 'completed' ||
              remoteCheck.status === 'cancelled'
            ) {
              console.log('🧹 Purging stale local session (completed or non-existent in DB)');
              resetSession();
            } else {
              loadFromLocalStorage();
            }
          } else {
            loadFromLocalStorage();
          }
        }
      } catch (err) {
        console.error('Session load failed:', err);
      } finally {
        setIsLoaded(true);
      }
    };

    loadSession();
    // eslint-disable-next-line react-hooks/exhaustive-deps -- Intentionally depends only on user.id; setter functions are stable and adding them would cause re-subscribe loops on every render
  }, [user?.id]);

  // 2. Real-time Monitor
  useEffect(() => {
    if (!activeListId || !user) return;

    let channel: ReturnType<typeof supabase.channel> | null = null;
    let retryTimeout: NodeJS.Timeout;
    // Polling fallback handle. When the realtime channel can't connect
    // after its own retries we drop to slow polling so the user still
    // sees status changes (takeovers, completions) — just at 30s
    // granularity instead of <1s. Cleared on cleanup or when the
    // channel finally reconnects.
    let pollTimer: ReturnType<typeof setInterval> | null = null;
    const POLL_INTERVAL_MS = 30_000;

    const stopPolling = () => {
      if (pollTimer) {
        clearInterval(pollTimer);
        pollTimer = null;
      }
    };

    const pollOnce = async () => {
      if (!activeListId) return;
      const { data, error } = await withSupabaseRetry(
        () =>
          supabase
            .from('picking_lists')
            .select(
              'status, user_id, checked_by, correction_notes, shipping_type, is_waiting_inventory'
            )
            .eq('id', activeListId)
            .maybeSingle(),
        { label: 'usePickingSync.pollFallback', maxAttempts: 2 }
      );
      if (error || !data) return;

      // Same fan-out as the realtime UPDATE handler below, but reusing
      // the refs to avoid double-firing on unchanged values.
      if (
        sessionModeRef.current === 'picking' &&
        data.user_id &&
        (data.user_id as string) !== user.id &&
        (data.user_id as string) !== ownerIdRef.current
      ) {
        showTakeoverAlert(data.user_id as string);
        return;
      }
      if (
        sessionModeRef.current === 'double_checking' &&
        data.checked_by &&
        (data.checked_by as string) !== user.id &&
        (data.checked_by as string) !== checkedByRef.current
      ) {
        showTakeoverAlert(data.checked_by as string);
        return;
      }
      if (data.status !== listStatusRef.current) {
        if (data.status === 'completed' || data.status === 'cancelled') {
          resetSession();
          stopPolling();
          return;
        }
        setListStatus(data.status as string);
      }
      // Note: shippingType/isWaitingInventory don't have stable refs to
      // compare against — accepting a possible no-op write here. React
      // bails out internally if value is identical.
      const shipNew = (data.shipping_type as string | null) ?? null;
      setShippingType(shipNew as string);
      const waitNew = !!data.is_waiting_inventory;
      setIsWaitingInventory(waitNew);
      if (data.correction_notes !== correctionNotesRef.current)
        setCorrectionNotes(data.correction_notes as string | null);
      if (data.checked_by !== checkedByRef.current) setCheckedBy(data.checked_by as string | null);
      if (data.user_id !== ownerIdRef.current) setOwnerId(data.user_id as string | null);
    };

    const showTakeoverAlert = async (takerId: string) => {
      if (takeoverSyncRef.current === activeListId) return;
      takeoverSyncRef.current = activeListId;

      try {
        const { data: profile } = await supabase
          .from('profiles')
          .select('full_name')
          .eq('id', takerId)
          .single();

        const takerName = profile?.full_name || 'Another user';

        toast(`${takerName} has taken over this order.\nYour session is being reset.`, {
          icon: 'ℹ️',
          duration: 4000,
          style: { border: '1px solid #3b82f6', padding: '16px', color: '#1e293b' },
        });

        setTimeout(() => {
          resetSession();
          takeoverSyncRef.current = null;
        }, 1500);
      } catch (err) {
        takeoverSyncRef.current = null;
        console.error('Error showing takeover alert:', err);
      }
    };

    let retryCount = 0;
    const setupSubscription = () => {
      const channelName = `list_status_sync_${activeListId}`;
      console.log(
        `🔌 [Realtime] Attempting connection to ${channelName}... (Attempt ${retryCount + 1}/3)`
      );

      // Ensure any previous zombie channel is cleaned
      if (channel) {
        supabase.removeChannel(channel);
        channel = null;
      }

      channel = supabase
        .channel(channelName)
        .on(
          'postgres_changes',
          {
            event: 'UPDATE',
            schema: 'public',
            table: 'picking_lists',
            filter: `id=eq.${activeListId}`,
          },
          (payload) => {
            const newData = payload.new;

            // Takeover detection: only alert if the field ACTUALLY CHANGED to a different user.
            // Without checking the ref, any UPDATE event (e.g., items change) would false-positive.
            if (
              sessionModeRef.current === 'picking' &&
              newData.user_id &&
              (newData.user_id as string) !== user.id &&
              (newData.user_id as string) !== ownerIdRef.current
            ) {
              showTakeoverAlert(newData.user_id as string);
              return;
            }

            if (
              sessionModeRef.current === 'double_checking' &&
              newData.checked_by &&
              (newData.checked_by as string) !== user.id &&
              (newData.checked_by as string) !== checkedByRef.current
            ) {
              showTakeoverAlert(newData.checked_by as string);
              return;
            }

            if (newData.status !== listStatusRef.current) {
              // TERMINAL STATUS AUTO-CLEANUP
              if (newData.status === 'completed' || newData.status === 'cancelled') {
                console.log(
                  `🏁 [PickingSync] List ${activeListId} reached terminal status: ${newData.status}. Resetting local session.`
                );
                resetSession();
                return; // Early exit, session is gone
              }
              setListStatus(newData.status as string);
            }
            // No previous-value compare needed — the setter is a
            // useState dispatch in the parent, and React bails on
            // identical values internally via Object.is. The function
            // form here only made tsc unhappy because the prop is typed
            // as the narrow `(s: string) => void` (no SetStateAction).
            const newShippingType =
              ((newData as Record<string, unknown>).shipping_type as string | null) ?? null;
            setShippingType(newShippingType as string);
            setIsWaitingInventory(!!(newData as Record<string, unknown>).is_waiting_inventory);
            if (newData.correction_notes !== correctionNotesRef.current)
              setCorrectionNotes(newData.correction_notes as string | null);
            if (newData.checked_by !== checkedByRef.current)
              setCheckedBy(newData.checked_by as string | null);
            if (newData.user_id !== ownerIdRef.current)
              setOwnerId(newData.user_id as string | null);

            if (
              sessionModeRef.current === 'double_checking' &&
              (newData.status === 'active' || newData.status === 'needs_correction')
            ) {
              if (newData.user_id === user.id) setSessionMode('picking');
            }
          }
        )
        .subscribe((status, err) => {
          console.log(`Network status for ${channelName}:`, status);

          if (status === 'SUBSCRIBED') {
            retryCount = 0; // Reset on success
            console.log(`✅ [Realtime] Subscribed to ${channelName}`);
            // Realtime is back — stop the polling fallback if it was on.
            stopPolling();
          }

          if (status === 'CHANNEL_ERROR' || status === 'TIMED_OUT' || status === 'CLOSED') {
            // CRITICAL: Only call removeChannel if NOT already closed to avoid infinite recursion
            if (status !== 'CLOSED' && channel) {
              supabase.removeChannel(channel);
              channel = null;
            }

            retryCount++;
            if (retryCount <= 3) {
              console.warn(
                `❌ [Realtime] Connection error (${status}). Retrying ${retryCount}/3 in 5s...`,
                err
              );
              retryTimeout = setTimeout(setupSubscription, 5000);
            } else {
              console.error(
                `❌ [Realtime] Max retries reached for ${channelName}. Falling back to polling every ${POLL_INTERVAL_MS / 1000}s.`
              );
              toast(
                'Live sync lost. Falling back to slow polling — changes from others may take up to 30s.',
                { duration: 5000, id: `sync-fallback-${activeListId}`, icon: '⚠️' }
              );
              // Start polling if not already running. We keep trying the
              // channel in the background via `setupSubscription` is NOT
              // retried here, but `refetchOnReconnect` + the next mount
              // will revive it.
              if (!pollTimer) {
                // Fire one poll immediately so the user isn't waiting
                // a full interval to catch up on whatever they missed.
                void pollOnce();
                pollTimer = setInterval(() => {
                  void pollOnce();
                }, POLL_INTERVAL_MS);
              }
            }
          }
        });
    };

    setupSubscription();

    return () => {
      console.log(`🧹 Cleaning up channel list_status_sync_${activeListId}`);
      if (channel) supabase.removeChannel(channel);
      if (retryTimeout) clearTimeout(retryTimeout);
      stopPolling();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps -- Subscribes to realtime channel; setter functions use refs to avoid re-subscribing on every state change
  }, [activeListId, user?.id]);

  // 3. Save Logic
  const saveToDb = async (
    items: CartItem[],
    userId: string,
    listId: string | null,
    orderNum: string | null
  ) => {
    if (!userId || isSyncingRef.current || sessionMode !== 'picking') return;

    isSyncingRef.current = true;
    setIsSaving(true);
    try {
      // Resolve the customer the same way generatePickingPath does: a manually
      // started order carries { name } with no id, so we must find-or-create the
      // customers row here — otherwise the typed customer name is dropped and the
      // order is saved with customer_id = null. Cache the id back into state so the
      // next debounced save reuses it (no repeated lookups / duplicate inserts).
      let resolvedCustomerId = customer?.id;
      if (!resolvedCustomerId && customer?.name?.trim()) {
        const name = customer.name.trim();
        const { data: existing } = await supabase
          .from('customers')
          .select('id')
          .eq('name', name)
          .maybeSingle();
        if (existing) {
          resolvedCustomerId = existing.id;
        } else {
          const { data: newCust } = await supabase
            .from('customers')
            .insert({ name })
            .select('id')
            .single();
          resolvedCustomerId = newCust?.id;
        }
        if (resolvedCustomerId) setCustomer({ ...customer, id: resolvedCustomerId });
      }

      const sanitizedItems = items; // Data already in correct format from database
      if (listId) {
        // Guard: never write merged group data back to DB.
        // Merged order_numbers contain ' / ' (e.g. "879270 / 879268").
        const isMergedGroup = orderNum?.includes(' / ');
        const updateData: Record<string, unknown> = {
          customer_id: resolvedCustomerId ?? null,
          load_number: loadNumber,
        };
        if (!isMergedGroup) {
          updateData.items = sanitizedItems as unknown as Json;
          updateData.order_number = orderNum;
        }
        const { error } = await supabase.from('picking_lists').update(updateData).eq('id', listId);
        if (error) throw error;
      } else if (items.length > 0) {
        const { data, error } = await supabase
          .from('picking_lists')
          .insert({
            user_id: userId,
            items: sanitizedItems as unknown as Json,
            status: 'active',
            order_number: orderNum,
            customer_id: resolvedCustomerId ?? null,
            load_number: loadNumber,
          })
          .select('*, customer:customers(*)')
          .single();
        if (error) throw error;
        if (data) {
          setActiveListId(data.id);
          setListStatus(data.status as string);
          setShippingType(
            ((data as Record<string, unknown>).shipping_type as string | null) ?? null
          );
          setIsWaitingInventory(!!(data as Record<string, unknown>).is_waiting_inventory);
          setOwnerId(data.user_id);
        }
      }
      setLastSaved(new Date());
    } catch (err) {
      console.error('Failed to sync picking session:', err);
    } finally {
      setIsSaving(false);
      isSyncingRef.current = false;
    }
  };

  // saveToDb is recreated every render, so ITS closure (customer, loadNumber,
  // sessionMode) is always fresh — but the debounce used to capture ONE frozen
  // saveToDb per sessionMode change. A customer assigned or edited mid-session
  // was then auto-saved with the PREVIOUS customer_id (or null), silently
  // relinking the order to another customer. The ref always points at the
  // latest closure; the debounce itself is created once. A save that fires
  // after leaving picking mode is skipped by saveToDb's own (now fresh)
  // sessionMode guard, which is what the old [sessionMode] recreate-and-cancel
  // achieved.
  const saveToDbRef = useRef(saveToDb);
  useEffect(() => {
    saveToDbRef.current = saveToDb;
  });

  const debouncedSaveRef = useRef<DebouncedFunction<
    (items: CartItem[], userId: string, listId: string | null, orderNum: string | null) => void
  > | null>(null);
  useEffect(() => {
    debouncedSaveRef.current = debounce(
      (items: CartItem[], userId: string, listId: string | null, orderNum: string | null) =>
        saveToDbRef.current(items, userId, listId, orderNum),
      SYNC_DEBOUNCE_MS
    );
    return () => {
      debouncedSaveRef.current?.cancel();
    };
  }, []);

  useEffect(() => {
    if (!isLoaded || !user || sessionMode !== 'picking') return;
    if (cartItems.length === 0 && !activeListId && isInitialSyncRef.current) {
      isInitialSyncRef.current = false;
      return;
    }
    if (debouncedSaveRef.current) {
      debouncedSaveRef.current(cartItems, user.id, activeListId, orderNumber);
      isInitialSyncRef.current = false;
    }
  }, [cartItems, orderNumber, activeListId, isLoaded, user, sessionMode]); // debouncedSaveRef is a ref, not needed in deps

  // 4. Load External List
  const loadExternalList = useCallback(
    async (listId: string) => {
      if (!user) return;

      // Force-save in-progress picking session before switching to verification.
      // In picking mode, sessions auto-sync via debounce, but the debounce may not
      // have fired yet. Flush it now to ensure the order is in DB before we overwrite state.
      if (sessionMode === 'picking' && cartItems.length > 0 && !activeListId && orderNumber) {
        try {
          const { data: saved } = await supabase
            .from('picking_lists')
            .insert({
              user_id: user.id,
              items: cartItems as unknown as Json,
              status: 'active',
              order_number: orderNumber,
            })
            .select('id')
            .single();
          if (saved) {
            console.log('💾 [loadExternalList] Flushed unsaved session to DB:', saved.id);
          }
        } catch (err) {
          console.error('Failed to flush session before switching:', err);
        }
      }

      setIsSaving(true);
      try {
        const { data, error } = await supabase
          .from('picking_lists')
          .select('*, customer:customers(*)')
          .eq('id', listId)
          .single();
        if (error) throw error;
        if (data) {
          let allItems = (data.items as unknown as CartItem[]) || [];
          let combinedOrderNumber = data.order_number || null;

          // If order belongs to a group, merge items from all sibling orders
          // for display in DoubleCheckView. The merged state is READ-ONLY —
          // write paths (saveToDb, markAsReady) must guard against writing it back.
          if (data.group_id) {
            const { data: siblings } = await supabase
              .from('picking_lists')
              .select('id, items, order_number')
              .eq('group_id', data.group_id)
              .neq('id', listId)
              .neq('status', 'completed')
              .neq('status', 'cancelled');

            if (siblings && siblings.length > 0) {
              const orderNumbers = [data.order_number];
              // Tag anchor items with their owning list_id so per-item RPCs
              // (pick_item / unpick_item) route to the correct picking_list.
              allItems = allItems.map((item) => ({
                ...item,
                source_order: item.source_order || data.order_number || 'unknown',
                source_list_id: item.source_list_id || (data.id as string),
              }));
              for (const sibling of siblings) {
                const siblingItems = (sibling.items as unknown as CartItem[]) || [];
                const taggedItems = siblingItems.map((item) => ({
                  ...item,
                  source_order: sibling.order_number || 'unknown',
                  source_list_id: sibling.id as string,
                }));
                allItems = [...allItems, ...taggedItems];
                if (sibling.order_number) orderNumbers.push(sibling.order_number);
              }
              combinedOrderNumber = orderNumbers.filter(Boolean).join(' / ');
            }
          }

          setCartItems(allItems);
          setActiveListId(data.id as string);
          setOrderNumber(combinedOrderNumber);
          setCustomer((data.customer as Customer) || null);
          setLoadNumber(data.load_number || null);
          setListStatus(data.status as string);
          setShippingType(
            ((data as Record<string, unknown>).shipping_type as string | null) ?? null
          );
          setIsWaitingInventory(!!(data as Record<string, unknown>).is_waiting_inventory);
          setCheckedBy(data.checked_by || null);
          setOwnerId(data.user_id || null);
          setCorrectionNotes(data.correction_notes || null);
          // Infer sessionMode from order status — callers can override after
          setSessionMode(
            data.status === 'reopened'
              ? 'reopened'
              : data.status === 'active' || data.status === 'needs_correction'
                ? 'picking'
                : 'double_checking'
          );
          return data;
        }
      } catch (err: unknown) {
        console.error('Failed to load external list:', err);
        showError('Load Error', err instanceof Error ? err.message : 'Unknown error');
      } finally {
        setIsSaving(false);
      }
    },
    [user, showError]
  );

  return { isLoaded, isSaving, lastSaved, loadExternalList };
};

